@Test
public void testBuildDoctype() {
    HtmlPageAttributes page = new HtmlPageAttributes();
    assertEquals("<!DOCTYPE html>", page.getDoctype("html", null, null));
    assertEquals("<!DOCTYPE html>", page.getDoctype("html", "", ""));
    assertEquals("<!DOCTYPE html SYSTEM \"bla\">", page.getDoctype("html", "", "bla"));
    assertEquals("<!DOCTYPE HTML PUBLIC \"-//W3C//DTD HTML 4.01 Transitional//EN\" " + "\"http://www.w3.org/TR/1999/REC-html401-19991224/loose.dtd\">", page.getDoctype(TurbineConstants.DEFAULT_HTML_DOCTYPE_ROOT_ELEMENT_DEFAULT, TurbineConstants.DEFAULT_HTML_DOCTYPE_IDENTIFIER_DEFAULT, TurbineConstants.DEFAULT_HTML_DOCTYPE_URI_DEFAULT));
    // HTML 5 is the default
    assertEquals("<!DOCTYPE HTML>", page.getDefaultDoctype());
}

@Test
public void testAddRemove() {
    assertFalse("TurbineURI should not have a pathInfo", turi.hasPathInfo());
    assertFalse("TurbineURI must not have a queryData", turi.hasQueryData());
    turi.addPathInfo("test", "x");
    assertTrue("TurbineURI must have a pathInfo", turi.hasPathInfo());
    assertFalse("TurbineURI must not have a queryData", turi.hasQueryData());
    turi.removePathInfo("test");
    assertFalse("TurbineURI must not have a pathInfo", turi.hasPathInfo());
    assertFalse("TurbineURI must not have a queryData", turi.hasQueryData());
    assertFalse("TurbineURI should not have a queryData", turi.hasQueryData());
    assertFalse("TurbineURI must not have a pathInfo", turi.hasPathInfo());
    turi.addQueryData("test", "x");
    assertTrue("TurbineURI must have a queryData", turi.hasQueryData());
    assertFalse("TurbineURI must not have a pathInfo", turi.hasPathInfo());
    turi.removeQueryData("test");
    assertFalse("TurbineURI must not have a queryData", turi.hasQueryData());
    assertFalse("TurbineURI must not have a pathInfo", turi.hasPathInfo());
}

@Test
public void testEmptyAndNullQueryData() {
    // Check empty String
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
    turi.addQueryData("test", "");
    assertEquals("/context/servlet/turbine?test=", turi.getRelativeLink());
    turi.removeQueryData("test");
    // Check null
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
    turi.addQueryData("test", null);
    assertEquals("/context/servlet/turbine?test=null", turi.getRelativeLink());
    turi.removeQueryData("test");
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
}

@Test
public void testEmptyAndNullPathInfo() {
    // Check empty String
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
    turi.addPathInfo("test", "");
    // Kind of susspect result - might result in "//" in the URL.
    assertEquals("/context/servlet/turbine/test/", turi.getRelativeLink());
    turi.removePathInfo("test");
    // Check null
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
    turi.addPathInfo("test", null);
    assertEquals("/context/servlet/turbine/test/null", turi.getRelativeLink());
    turi.removePathInfo("test");
    assertEquals("/context/servlet/turbine", turi.getRelativeLink());
}

